import React, { useState, useRef, useEffect } from 'react';
import './App.css';

function App() {
  const [file, setFile] = useState(null);
  const [question, setQuestion] = useState('');
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState('loading');
  const messagesEndRef = useRef(null);

  // Get mode on load
  useEffect(() => {
    fetch('http://localhost:8000/')
      .then(res => res.json())
      .then(data => setMode(data.mode))
      .catch(() => setMode('unknown'));
  }, []);

  // Auto scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const uploadPDF = async () => {
    if (!file) {
      alert('Please select a PDF file');
      return;
    }

    const formData = new FormData();
    formData.append('file', file);
    
    setLoading(true);
    addMessage('system', `Uploading ${file.name}...`);
    
    try {
      const res = await fetch('http://localhost:8000/upload', {
        method: 'POST',
        body: formData
      });
      const data = await res.json();
      
      if (res.ok) {
        addMessage('system', `✅ ${data.message} (${data.chunks} chunks created)`);
      } else {
        addMessage('system', `❌ Upload failed: ${data.detail || 'Unknown error'}`);
      }
    } catch (err) {
      addMessage('system', '❌ Cannot connect to backend. Make sure it\'s running on port 8000');
    }
    setLoading(false);
    setFile(null);
  };

  const askQuestion = async () => {
    if (!question.trim()) return;
    
    const userQuestion = question;
    setQuestion('');
    addMessage('user', userQuestion);
    setLoading(true);
    
    try {
      const res = await fetch(`http://localhost:8000/ask?question=${encodeURIComponent(userQuestion)}`, {
        method: 'POST'
      });
      const data = await res.json();
      
      if (data.error) {
        addMessage('bot', `❌ ${data.error}`);
      } else {
        addMessage('bot', data.answer);
        if (data.sources) {
          addMessage('system', `📚 Found ${data.sources} relevant sections`);
        }
      }
    } catch (err) {
      addMessage('bot', '❌ Error getting answer. Make sure backend is running.');
    }
    setLoading(false);
  };

  const addMessage = (role, content) => {
    setMessages(prev => [...prev, { role, content, id: Date.now() }]);
  };

  return (
    <div className="app">
      <header>
        <h1>🤖 RAG Chatbot</h1>
        <div className="mode-badge">
          {mode === 'EXE' ? '💻 Desktop Mode' : mode === 'HOSTED' ? '☁️ Cloud Mode' : '🔄 Loading...'}
        </div>
      </header>

      <div className="upload-section">
        <div className="upload-box">
          <input 
            type="file" 
            accept=".pdf" 
            onChange={(e) => setFile(e.target.files[0])}
            id="file-input"
            hidden
          />
          <label htmlFor="file-input" className="upload-label">
            📄 {file ? file.name : 'Click to select PDF'}
          </label>
          <button onClick={uploadPDF} disabled={loading || !file}>
            Upload PDF
          </button>
        </div>
      </div>

      <div className="chat-section">
        <div className="messages-container">
          {messages.length === 0 ? (
            <div className="welcome">
              <h3>Welcome! 👋</h3>
              <p>1. Upload a PDF document</p>
              <p>2. Ask questions about it</p>
              <p>3. Get instant answers!</p>
            </div>
          ) : (
            messages.map((msg) => (
              <div key={msg.id} className={`message ${msg.role}`}>
                <div className="avatar">
                  {msg.role === 'user' ? '👤' : msg.role === 'bot' ? '🤖' : 'ℹ️'}
                </div>
                <div className="content">
                  {msg.content}
                </div>
              </div>
            ))
          )}
          {loading && (
            <div className="typing">
              <span>🤖</span>
              <span>Thinking</span>
              <span>.</span><span>.</span><span>.</span>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        <div className="input-area">
          <textarea
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && !e.shiftKey && askQuestion()}
            placeholder="Ask anything about your PDF..."
            rows="2"
          />
          <button onClick={askQuestion} disabled={loading}>
            Send 📨
          </button>
        </div>
      </div>
    </div>
  );
}

export default App;
